recognized_test_commands.command:
/bin/bash -lc "cat >> .codex-role-output/checkpoint.md <<'EOF'

Root cause: config.Image has only Name/Tag, IsValidImage requires Tag, scanImage constructs Name:Tag, conversion drops digest, report UUID naming constructs Name:Tag, and image OS detection embeds Tag in the generated server name. A working tag reference follows the same path; digest input has no field to survive it. Hypothesis: adding Digest to both image types and selecting one full reference at each construction point resolves the data loss and ambiguity.
EOF
cat > config/image_digest_test.go <<'EOF'
package config

import \"testing\"

func TestImageDigestReference(t *testing.T) {
	cases := []struct {
		image Image
		full string
		err  string
	}{
		{Image{}, \"\", \"Invalid arguments : no image name\"},
		{Image{Name: \"registry/app\"}, \"registry/app:\", \"Invalid arguments : no image tag and digest\"},
		{Image{Name: \"registry/app\", Tag: \"v1\"}, \"registry/app:v1\", \"\"},
		{Image{Name: \"registry/app\", Digest: \"sha256:abc\"}, \"registry/app@sha256:abc\", \"\"},
		{Image{Name: \"registry/app\", Tag: \"v1\", Digest: \"sha256:abc\"}, \"registry/app@sha256:abc\", \"Invalid arguments : you can either set image tag or digest\"},
	}
	for _, tc := range cases {
		if got := tc.image.GetFullName(); got "'!= tc.full {
			t.Errorf("GetFullName(%+v) = %q, want %q", tc.image, got, tc.full)
		}
		err := IsValidImage(tc.image)
		if tc.err == "" && err != nil || tc.err != "" && (err == nil || err.Error() != tc.err) {
			t.Errorf("IsValidImage(%+v) = %v, want %q", tc.image, err, tc.err)
		}
	}
}
EOF
go test ./config -run TestImageDigestReference -count=1'
